        && active_segment
            != base + SCRATCH_SEGMENT_SLOTS_BASE + 3 * sizeof(SubSegment)
        && active_segment
            != base + SCRATCH_SEGMENT_SLOTS_BASE + 4 * sizeof(SubSegment)
        && (level_mode == 0
